mapper.select:
SELECT id, audit_category, operator_id, operator_name, action, target_type, target_id,
       detail_before, detail_after, result, fail_reason, transaction_id,
       client_ip, user_agent, trace_id, event_time, created_at
FROM sys_audit_log
WHERE event_time >= #{startTime}
  AND event_time <= #{endTime}

    AND audit_category = #{category}


    AND operator_id = #{operatorId}


    AND action = #{action}


    AND target_type = #{targetType}


    AND target_id = #{targetId}


    AND result = #{result}


    AND id < #{lastId}

ORDER BY id DESC
LIMIT #{limit}
